#include "KS/SRC/ks/GraphicalMenuSystem_shared.h"

class entity;

class BeachFrontEnd {
public:
    void SkipSlide(bool in);
};

class FEManager {
public:
    void *IGO;
    void *pms;
    GraphicalMenuSystem *gms;
};

class game {
    char padding[0x258];
    int surferIdx[2];

public:
    int GetSurferIdx(int hero_num) const { return surferIdx[hero_num]; }
};

extern game *g_game_ptr;

class FEEntityManager {
public:
    enum {
        STATE_MAIN,
        STATE_SURFER1,
        STATE_SURFER2,
        STATE_TRICK,
        STATE_BEACH,
        STATE_BOARD,
        STATE_OTHER_SET,
        STATE_OTHER
    };
    enum {
        CAM_POS_WALL_1,
        CAM_POS_WALL_2_IN,
        CAM_POS_WALL_2_OUT,
        CAM_POS_WALL_3_MAP,
        CAM_POS_WALL_3_CLOSET,
        CAM_POS_WALL_4,
        CAM_POS_END
    };

    entity *surfer_ent;
    bool mm_anims_loaded;
    bool all_loaded;
    float camera_roll_time;
    int camera_roll_stop;
    int surfer_anim_count;
    int current_surfer_index;
    int previous_surfer_index[2];
    int loading_surfer_index;
    int loading_surfer_ent;
    int surfer_index_2;
    int current_board_index;
    FEManager *manager;
    char fields_to_cur_state[0x240 - 0x38];
    int cur_state;
    int last_state;
    bool op_ext;

    bool UpdateSurferIndex(int csi, bool force_load = false);
    void ToBeachSelect();
    void SetSurferPo(entity *surfer, int surfer_num);
    void CameraAnim(int anim_pos, float start_time = -2.0f);
    void moveClosetDoor(bool door_left, bool open);
};

__asm__(".equ g_game_ptr, 0x0045AC64");
__asm__(".equ SkipSlide__13BeachFrontEndb, 0x0018EE50");
__asm__(".equ UpdateSurferIndex__15FEEntityManagerib, 0x001C2450");
__asm__(".equ CameraAnim__15FEEntityManagerif, 0x001C4E28");
__asm__(".equ moveClosetDoor__15FEEntityManagerbT1, 0x001C50E0");
__asm__(".equ SetSurferPo__15FEEntityManagerP6entityi, 0x001C9298");

void FEEntityManager::ToBeachSelect()
{
    if(!all_loaded) manager->gms->LoadAll();
    ((BeachFrontEnd *)manager->gms->menus[GraphicalMenuSystem::BeachMenu])->SkipSlide(true);

    if (!surfer_ent)
    {
        if ((manager->gms->multiplayer && manager->gms->multi_1) || !manager->gms->multiplayer)
            UpdateSurferIndex(g_game_ptr->GetSurferIdx(0));
        else
            UpdateSurferIndex(g_game_ptr->GetSurferIdx(1));
    }

    SetSurferPo(surfer_ent, loading_surfer_index);

    CameraAnim(CAM_POS_WALL_3_MAP);
    moveClosetDoor(true, false);
    op_ext = false;
    cur_state = STATE_BEACH;
}
